import contextlib, csv, gc, hashlib, io, json, os, subprocess, sys, tempfile
from pathlib import Path
PINS = {'scientific_commit': 'e84673e3d834563b333bb482e196e0334e4f6e0a', 'source_hash': '8f102b93c9db2bdf32a6bfa0e10afdfea83ee605dfdd748dd8bf9d864d07f219', 'config_sha256': 'ec6d751a5d8e1b323165f5126528291d731d03cc9c0fc3426b0c8ad938376d4c'}
ROOT = Path('/home/imss/cw/CLIPDenoising_C_20261021')
SNAPSHOT = True
ADAPTER = Path('/tmp/summarize_g1c_only_20261021_895d2cce516c076a.py')
ADAPTER_SHA256 = '895d2cce516c076a77f6a6718a2a140461b85506306b6e8bffacbdd9fb4458dc'
os.chdir(ROOT)
sys.path.insert(0, str(ROOT))
with contextlib.redirect_stdout(io.StringIO()):
    from tools.experiment_common import load_paths, read_json, sha256_file, source_hash, digest, utc_now
    if source_hash() != PINS['source_hash']:
        raise RuntimeError('Remote scientific source changed')
    head = subprocess.check_output(['git','rev-parse','HEAD'], cwd=ROOT, text=True).strip()
    if head != PINS['scientific_commit']:
        raise RuntimeError('Remote git HEAD differs from pinned scientific commit')
    config_path = ROOT / 'configs/plan_c_only_server.yaml'
    if sha256_file(config_path) != PINS['config_sha256']:
        raise RuntimeError('Remote paths config differs from pin')
    paths = load_paths(config_path)
    if Path(paths['output_root']).resolve() != ROOT/'runs/c_only' or Path(paths['reports_dir']).resolve() != ROOT/'reports/c_only':
        raise RuntimeError('Unexpected pipeline artifact directories')
    state_path = ROOT/'runs/c_only/pipeline_state.json'
    state = read_json(state_path)
    if state['identity'] != {'source_hash':PINS['source_hash'],'config_sha256':PINS['config_sha256']}:
        raise RuntimeError('Pipeline identity differs')
    audit = {'schema':'c_full_independent_publication_audit_v1','at':utc_now(),
             'source_hash':PINS['source_hash'],'scientific_commit':head,'config_sha256':PINS['config_sha256'],
             'mode':'snapshot' if SNAPSHOT else 'complete','publication_ready':False,
             'pipeline_status':state.get('status'),'pipeline_phase':state.get('phase'),
             'scope':['G1C'],'paused_variants':['C'],'two_variant_pipeline_completed':False}
    if not SNAPSHOT:
        if sha256_file(ADAPTER)!=ADAPTER_SHA256:
            raise RuntimeError('Private single-variant report adapter changed')
        training_state=read_json(ROOT/'runs/c_only/full/G1C/seed0/status.json')
        if training_state.get('status')!='completed' or training_state.get('update')!=300000:
            raise RuntimeError('G1C training is not fully completed')
        from tools.evaluate_c_only import validated_gate, load_historical, historical_baseline, verify_baseline_checkpoint
        input_audit = read_json(ROOT/'reports/c_only/input_parity_audit.json')
        if input_audit.get('accepted') is not True or input_audit.get('status')!='passed' or input_audit.get('source_hash')!=PINS['source_hash']:
            raise RuntimeError('Historical input preflight was not accepted for the frozen source')
        csv_path, reference, historical = load_historical(paths)
        audits = {}
        for variant,baseline in [('G1C','G1')]:
            config, checkpoint_path, checkpoint, contract = validated_gate(paths,variant)
            del checkpoint
            gc.collect()
            if config['git_commit'] != head:
                raise RuntimeError('Training config executed commit differs')
            old_rows, identity = historical_baseline(csv_path,baseline,reference)
            old_proof = verify_baseline_checkpoint(paths,baseline,identity)
            evaluation = read_json(ROOT/f'reports/c_only/evaluation/{variant}/seed0/summary.json')
            if evaluation['contract'] != contract or evaluation['contract_hash'] != digest(contract):
                raise RuntimeError('Evaluation contract does not match current validated training')
            if evaluation['identity']['checkpoint_sha256'] != sha256_file(checkpoint_path):
                raise RuntimeError('Evaluation checkpoint differs from validated final checkpoint')
            preflight = read_json(ROOT/f'reports/c_only/actual_{variant}_contract.json')
            if preflight.get('accepted') is not True or preflight.get('variant')!=variant or preflight.get('source_hash')!=PINS['source_hash']:
                raise RuntimeError('Actual-model preflight was not accepted')
            audits[variant] = {'verified_updates':300000,'training_proof_sha256':contract['proof_sha256'],
                              'contract_hash':digest(contract),'checkpoint_sha256':sha256_file(checkpoint_path),
                              'baseline_checkpoint_proof':old_proof}
        official = ROOT/'reports/c_only/g1c_final'
        original = read_json(official/'summary.json')
        with tempfile.TemporaryDirectory(prefix='clip_c_full_independent_',dir='/tmp') as temporary:
            command=[sys.executable,str(ADAPTER),'--project-root',str(ROOT),'--paths',str(config_path),
                     '--input',str(ROOT/'reports/c_only/evaluation'),'--output',temporary]
            recalculation=subprocess.run(command,capture_output=True,text=True,timeout=1200)
            if recalculation.returncode:
                raise RuntimeError('Private single-G1C independent recomputation failed: '+recalculation.stderr[-2000:])
            recalculated=read_json(Path(temporary)/'summary.json')
            if {k:v for k,v in recalculated.items() if k!='completed_at'} != {k:v for k,v in original.items() if k!='completed_at'}:
                raise RuntimeError('Independently recomputed final summary differs')
            for name, expected in recalculated['artifact_sha256'].items():
                source = official/name
                if not source.resolve().is_relative_to(official.resolve()) or sha256_file(source)!=expected:
                    raise RuntimeError('Recomputed CSV/report/panel differs: '+name)
        counts = {'rows':6300,'new_measurement_rows':3150,'reused_baseline_rows':3150,'paired_rows':3150,
                  'full_condition_rows':120,'table1_rows':6,'table1_seedwise_rows':6,'fixed_panels':6}
        if any(original.get(k)!=v for k,v in counts.items()) or original.get('completed') is not True:
            raise RuntimeError('Final report row counts differ from preregistered scope')
        actual_counts={}
        with (official/'per_image_results.csv').open(newline='',encoding='utf-8') as stream:
            for row in csv.DictReader(stream):
                actual_counts[row['experiment']]=actual_counts.get(row['experiment'],0)+1
        if actual_counts != {'G1':3150,'G1C':3150}:
            raise RuntimeError('Actual final CSV lacks the 3150 new + 3150 reused rows')
        audit.update(publication_ready=True,training=audits,counts=counts,actual_csv_counts=actual_counts,
                     final_summary_sha256=sha256_file(official/'summary.json'),
                     recalculated_artifact_sha256=original['artifact_sha256'],
                     adapter_sha256=ADAPTER_SHA256,
                     limitation='Single G1C only; C paused by user; old two-variant pipeline incomplete. Independent recomputation uses frozen aggregation plus the pinned private scope adapter; no new inference')
    candidates = [ROOT/p for p in ['reports/c_only/actual_C_contract.json', 'reports/c_only/actual_G1C_contract.json', 'reports/c_only/input_parity_audit.json', 'reports/c_only/progress.md', 'runs/c_only/pipeline_state.json']]
    for variant in ['C','G1C']:
        candidates += [ROOT/f'runs/c_only/full/{variant}/seed0'/p for p in ('manifest.json', 'status.json', 'summary.json', 'training_checks.json', 'input_protection.json', 'effective_config.json', 'checkpoints/latest.json')]
    if not SNAPSHOT:
        for directory in [ROOT/'reports/c_only/g1c_final',ROOT/'reports/c_only/evaluation/G1C/seed0']:
            for item in directory.rglob('*'):
                if item.is_symlink():
                    raise RuntimeError('Symlink in public report tree')
                if item.is_file() and item.suffix.lower() in {'.json','.csv','.md','.png'}:
                    candidates.append(item)
    files=[]
    for item in sorted(set(candidates)):
        if not item.exists():
            if SNAPSHOT or '/full/C/' in item.as_posix(): continue
            raise RuntimeError('Required metadata missing: '+str(item))
        if item.is_symlink() or not item.is_file() or not item.resolve().is_relative_to(ROOT):
            raise RuntimeError('Export path is not a regular file inside the frozen root')
        size=item.stat().st_size
        if size>64*1024**2: raise RuntimeError('Public artifact is unexpectedly large')
        files.append({'path':item.relative_to(ROOT).as_posix(),'bytes':size,'sha256':sha256_file(item)})
    if sum(item['bytes'] for item in files)>1024**3:
        raise RuntimeError('Public export exceeds its size limit')
    if read_json(state_path)!=state or source_hash()!=PINS['source_hash']:
        raise RuntimeError('Pipeline/source changed during audit')
    audit['files']=files
print(json.dumps(audit,allow_nan=False))
